mapper.select:
SELECT symbol, last_price, bid, ask, quote_as_of
FROM (
    SELECT DISTINCT ON (quote_as_of, price)
           id, symbol, price AS last_price, bid, ask, quote_as_of
    FROM price_history
    WHERE symbol = #{symbol}
    ORDER BY quote_as_of, price, id DESC
) updates
ORDER BY quote_as_of DESC, id DESC
LIMIT #{limit}

SELECT symbol, last_price, bid, ask, quote_as_of
FROM (
    SELECT DISTINCT ON (quote_as_of, price)
           id, symbol, price AS last_price, bid, ask, quote_as_of
    FROM price_history
    WHERE symbol = #{symbol}
      AND quote_as_of >= #{since}
    ORDER BY quote_as_of, price, id DESC
) updates
ORDER BY quote_as_of DESC, id DESC
